def construct_tree(n, d, k):
    if d >= n or k == 1 and n > 2:
        return "NO"

    edges = []
    current_level = 1

    for i in range(1, d + 1):
        edges.append((i, i + 1))

    current_level = d + 1
    for i in range(d + 2, n + 1):
        for j in range(1, k):
            if current_level < i:
                edges.append((i, current_level + j))
            else:
                break
        current_level += 1

    if len(edges) != n - 1:
        return "NO"

    return "YES\n" + "\n".join(f"{u} {v}" for u, v in edges)

